FormulaFieldDefinitions.FormulaFieldDefinition:
If {?Pm-OINV.DocCur} ={?Pm-OADM.MainCurncy} Then
(
    If {ORCT.DocCurr} = {?Pm-OADM.MainCurncy} Then
         {RCT2.BfDcntSum} - {RCT2.DcntSum}
    Else
        ({ORCT.CashSumFC} + {ORCT.TrsfrSumFC} + {ORCT.CredSumFC} + {ORCT.CheckSumFC}) * 
                ({RCT2.BfDcntSum} - {RCT2.DcntSum}) / {ORCT.DocTotal}
)
Else 
(
    If  {ORCT.DocCurr} = {?Pm-OADM.MainCurncy} Then
        {RCT2.BfDcntSum} - {RCT2.DcntSum}
    Else If {ORCT.DocCurr} = {?Pm-OINV.DocCur} Then
        {RCT2.BfDcntSumF} - {RCT2.DcntSumFC}
    Else
        ({ORCT.CashSumFC} + {ORCT.TrsfrSumFC} + {ORCT.CredSumFC} + {ORCT.CheckSumFC}) * 
                ({RCT2.BfDcntSum} - {RCT2.DcntSum}) / {ORCT.DocTotal}
)

Shared StringVar allRemarks;
Shared NumberVar  rctNumber;
StringVar  temp;
Shared NumberVar paymentRemarkCount := DistinctCount({ORCT.DocNum});

If rctNumber <> {ORCT.DocNum} Then
(
    If Not IsNull({ORCT.Comments}) Then
    (
        //paymentRemarkCount := paymentRemarkCount + 1;
        temp := '(' + {@__Payment} + ' ' + ToText({ORCT.DocNum}, 0) + ') ' + {ORCT.Comments};
        temp := temp + Chr(13);
        allRemarks := allRemarks + temp;
    );
    rctNumber := {ORCT.DocNum};
);

allRemarks

Shared BooleanVar displayInCreditCard := false;
Shared BooleanVar displayInCheck := false;
Shared BooleanVar displayInBank := false;

If Maximum({ORCT.CashSum})<> 0 OR Minimum({ORCT.CashSum})<> 0 
OR Maximum({ORCT.CheckSum}) <> 0 OR Minimum({ORCT.CheckSum}) <> 0
OR Maximum({ORCT.TrsfrSum}) <> 0  OR Minimum({ORCT.TrsfrSum}) <> 0 Then
    displayInCreditCard := false
Else
    displayInCreditCard := true;


If Maximum({ORCT.CashSum})<> 0 OR Minimum({ORCT.CashSum})<> 0 
OR Maximum({ORCT.TrsfrSum}) <> 0  OR Minimum({ORCT.TrsfrSum}) <> 0 Then
    displayInCheck := false
Else
    displayInCheck := true;

If Maximum({ORCT.CashSum})<> 0 OR Minimum({ORCT.CashSum})<> 0 Then
    displayInBank := false
Else
    displayInBank := true;

true

shared numbervar WTInPayment;
if {OCDC.Freight} = 'Y' then
 select {OINV.CurSource}
    case 'L': {?Pm-@TotalBeforeTax}* (1-{CDC1.Discount}/100.0)
    case 'S': {?Pm-@TotalBeforeTax}* (1-{CDC1.Discount}/100.0)
    case 'C': {?Pm-@TotalBeforeTax}* (1-{CDC1.Discount}/100.0)
    default: 0
else
  select {OINV.CurSource}
    case 'L': ({?Pm-@TotalBeforeTax} - {OINV.TotalExpns})* (1-{CDC1.Discount}/100.0) + {OINV.TotalExpns}
    case 'S': ({?Pm-@TotalBeforeTax} - {OINV.TotalExpSC})* (1-{CDC1.Discount}/100.0) + {OINV.TotalExpSC}
    case 'C': ({?Pm-@TotalBeforeTax} - {OINV.TotalExpFC})* (1-{CDC1.Discount}/100.0) + {OINV.TotalExpFC}
    default: 0

DateTimeVar baseDate;

Select {OCTG.BslineDate}
Case 'T' : baseDate := {OINV.TaxDate}
Case 'P' : baseDate := {OINV.DocDate}
default  : baseDate := {OINV.DocDate};

If {OCDC.ByDate} = 'Y' Then
    (baseDate := DateAdd('m', {CDC1.Month}, baseDate);
    Date(Year(baseDate), Month(baseDate), {CDC1.Day}))
Else
    DateAdd('d', {CDC1.NumOfDays}, baseDate)

NumberVar ratio;

If {OCDC.Tax} = 'Y' Then
    ratio := (100-{CDC1.Discount})
Else
    ratio := 100;

if {OCDC.Freight} = 'Y' then
    Select {OINV.CurSource}
    Case 'L' : {OINV.VatSum}* ratio/100.0
    Case 'C' : {OINV.VatSumFC}* ratio/100.0
    Case 'S' : {OINV.VatSumSy}* ratio/100.0
    Default: 0
Else    
    Select {OINV.CurSource}
    Case 'L' : ({OINV.VatSum}-{OINV.TaxOnExp})* ratio/100.0 + {OINV.TaxOnExp}
    Case 'C' : ({OINV.VatSumFC} - {OINV.TaxOnExpFc})* ratio/100.0 + {OINV.TaxOnExpFc}
    Case 'S' : ({OINV.VatSumSy}- {OINV.TaxOnExpSc}) * ratio/100.0 + {OINV.TaxOnExpSc}
    Default: 0

