FormulaFieldDefinitions.FormulaFieldDefinition:
//Esto deberia de estar en una Tabla pero es Una validacion
//de un campo de Usuario
//select * from UFD1  where TableID = 'adm1' and FieldId = 0

select {ADM1.U_B1SYS_VATCtg}
case  'RI' : "Responsable Inscripto"
case  'RNI' : "Responsable No Inscripto"
case  'MT' : "Monotributo"
case  'EX' : "Exento"
case  'NG' : "No Gravado"
default : "Responsable Inscripto"

// Poner lo que se quiera
// y poner //
//

{OADM.CompnyName}

//"Nombre de la Compania S.A."

//A Mano
//"Calle Facturacion 9999" + chr(13) +
//"B9999ICQ - Localidad - Provincia" + chr(13) +
//"Pais"
//Campos ADM1
{ADM1.Street} + chr(13) +
"(" + {ADM1.ZipCode} + ")"  +
{ADM1.City} + " - "  +
{OCRY.Name}

// Poner lo que se quiera
// y poner //
//
//"e-mail: mail@compania.com"
"E-mail: " +{OADM.E_Mail}

// Poner lo que se quiera
// y poner //
//
//"www.compania.com"
{ADM1.IntrntAdrs}

