ObjectFormatConditionFormulas.EnableSuppress:
//IF {?Pm-OINV.Letter} = "B" OR {?Pm-OINV.Letter} = "E" 
//THEN TRUE
//ELSE
//FALSE 
//
IF ({?Pm-OINV.Letter} = "B" OR {?Pm-OINV.Letter} = "E" ) 
AND {?Pm-@WithholdingTax} = 0 
THEN TRUE
ELSE 
FALSE

FormulaFieldDefinitions.FormulaFieldDefinition:
//if {TAX1.SrcArrType} = 12 then
//(
//    Select {?Pm-OINV.CurSource}
//    Case 'L':{TAX1.BaseSum} * 100/(100 - {?Pm-@CashDiscountPrcnt})
//    Case 'S':{TAX1.BaseSumSc}* 100/(100 - {?Pm-@CashDiscountPrcnt})
//    Case 'C':{TAX1.BaseSumFc}* 100 /(100 - {?Pm-@CashDiscountPrcnt})
//    Default: 1
//)
//else
//(
//    Select {?Pm-OINV.CurSource}
//    Case 'L':{TAX1.BaseSum}
//    Case 'S':{TAX1.BaseSumSc}
//    Case 'C':{TAX1.BaseSumFc}
//    Default: 1
//);

//IF {OINV.LETTER} = "B"  
//THEN {INV1.LineTotal} * ({INV1.VatPrcnt}/100 + 1)
IF {OINV.LETTER} = "B" AND  {OINV.CurSource} = 'L' 
THEN {INV1.LineTotal} * ({INV1.VatPrcnt}/100 + 1)
ELSE 
IF {OINV.LETTER} = "B" AND  {OINV.CurSource} = 'S' 
THEN {INV1.TotalSumSy}
ELSE 
if {OINV.LETTER} = "B" AND {OINV.CurSource} = 'C'
THEN {INV1.TotalFrgn}
// 
ELSE 
//A O E
IF {OINV.LETTER} = "A" AND {OINV.CurSource} = 'L'
then {INV1.LineTotal}
ELSE 
IF {OINV.LETTER} = "A" AND {OINV.CurSource} = 'S'
then {INV1.TotalSumSy}
ELSE
IF {OINV.LETTER} = "A" AND {OINV.CurSource} = 'C'
then {INV1.TotalFrgn}

