FormulaFieldDefinitions.FormulaFieldDefinition:
if {UTX1.SrcArrType} = 12 then
(
    Select {?Pm-OINV.CurSource}
    Case 'L':{UTX1.BaseSum} * 100/(100 - {?Pm-@CashDiscountPrcnt})
    Case 'S':{UTX1.BaseSumSc}* 100/(100 - {?Pm-@CashDiscountPrcnt})
    Case 'C':{UTX1.BaseSumFc}* 100 /(100 - {?Pm-@CashDiscountPrcnt})
    Default: 0
)
else
(
    Select {?Pm-OINV.CurSource}
    Case 'L':{UTX1.BaseSum}
    Case 'S':{UTX1.BaseSumSc}
    Case 'C':{UTX1.BaseSumFc}
    Default: 0
);

