  Pares   := 0;
  Impares := 0;

  for i := 1 to Length(Codigo) do
  (
    if (i mod 2) = 0 Then
        Pares := Pares + tonumber(mid(Codigo, I, 1))
    else
        Impares := Impares + tonumber(mid(Codigo, I, 1))

  );

  Digito :=  totext(10 - ((Pares + (3 * Impares)) Mod 10),0);

if Digito = "10" then
    Digito := "0";



  Result := Codigo + Digito;

